"""Discard Hold'em bot.

Strategy: range-weighted Monte Carlo equity + online opponent modelling.
  * Vectorised numpy hand evaluator (any 5-7 cards).
  * Opponent hands are sampled, then weighted by how consistent they are with the
    opponent's actions (preflop table percentile, postflop strength percentile,
    and the exposed discard), using thresholds learned from the opponent's own
    frequencies during this leg.
  * Decisions compare range equity with pot odds; bluff / value sizing adapts to
    how often the opponent folds.
All debug output goes to stderr.
"""
import sys
import json
import time
import math
import random
from itertools import combinations, permutations

import numpy as np

RANKS = "23456789TJQKA"
SUITS = "shdc"
CARD_ID = {r + s: i * 4 + j for i, r in enumerate(RANKS) for j, s in enumerate(SUITS)}
ID_CARD = {v: k for k, v in CARD_ID.items()}

RNG = np.random.default_rng()

# Strategy parameters. PB_PARAMS (JSON) overrides them for local A/B testing only;
# it is never set in the tournament.
P = {
    "open_t": 0.50, "limp_t": 0.42, "open_size": 0.75, "bb_raise_t": 0.60,
    "pf_reraise_t": 0.62, "pf_call_margin": 0.04,
    "raise_t": 0.68, "call_margin": 0.03, "bluff_raise": 0.3,
    "bet_t": 0.58, "bet_base": 0.45, "bet_slope": 2.4, "bluff_scale": 2.5,
    "disc_w": 0.35, "agg_floor": 0.08, "mdf": 0.0,
}
try:
    import os
    P.update(json.loads(os.environ.get("PB_PARAMS", "{}")))
except Exception:
    pass

# ------------------------------------------------------------------ lookup tables

M = 1 << 13
POP = np.array([bin(m).count("1") for m in range(M)], dtype=np.int64)


def _topk(m, k):
    out = 0
    for r in range(12, -1, -1):
        if k == 0:
            break
        if m >> r & 1:
            out |= 1 << r
            k -= 1
    return out


def _straight(m):
    for hi in range(12, 3, -1):
        w = 0b11111 << (hi - 4)
        if m & w == w:
            return hi + 1
    if m & 0b1000000001111 == 0b1000000001111:  # wheel A-2-3-4-5
        return 4
    return 0


TOP1 = np.array([_topk(m, 1) for m in range(M)], dtype=np.int64)
TOP2 = np.array([_topk(m, 2) for m in range(M)], dtype=np.int64)
TOP3 = np.array([_topk(m, 3) for m in range(M)], dtype=np.int64)
TOP5 = np.array([_topk(m, 5) for m in range(M)], dtype=np.int64)
_STR = [_straight(m) for m in range(M)]
STRAIGHT = np.array(_STR, dtype=np.int64)
# number of distinct ranks that would complete a straight (2 = open-ended, 1 = gutshot)
DRAW = np.array([0 if _STR[m] else
                 min(2, sum(1 for x in range(13) if not m >> x & 1 and _STR[m | 1 << x]))
                 for m in range(M)], dtype=np.int64)
W13 = (1 << np.arange(13)).astype(np.int64)
SUBMASK = (1 << 26) - 1


def evaluate(cards):
    """cards: int array (N, k), k in 5..7 -> int64 scores (higher is better)."""
    N, k = cards.shape
    R = cards >> 2
    S = cards & 3
    bits = np.left_shift(1, R).astype(np.int64)
    rows = np.arange(N)
    cnt = np.zeros((N, 13), dtype=np.int8)
    for j in range(k):
        cnt[rows, R[:, j]] += 1
    rmask = np.bitwise_or.reduce(bits, axis=1)
    fmask = np.zeros(N, dtype=np.int64)
    for s in range(4):
        sm = np.bitwise_or.reduce(np.where(S == s, bits, 0), axis=1)
        fmask = np.where(POP[sm] >= 5, sm, fmask)
    ge2 = (cnt >= 2) @ W13
    ge3 = (cnt >= 3) @ W13
    ge4 = (cnt >= 4) @ W13
    t3 = TOP1[ge3]
    fh_pair = TOP1[ge2 & ~t3]
    sf = STRAIGHT[fmask]
    st = STRAIGHT[rmask]
    conds = [sf > 0, ge4 > 0, (ge3 > 0) & (fh_pair > 0), fmask > 0, st > 0,
             ge3 > 0, POP[ge2] >= 2, ge2 > 0]
    p2 = TOP2[ge2]
    vals = [
        (8 << 26) | sf,
        (7 << 26) | (ge4 << 13) | TOP1[rmask & ~ge4],
        (6 << 26) | (t3 << 13) | fh_pair,
        (5 << 26) | TOP5[fmask],
        (4 << 26) | st,
        (3 << 26) | (t3 << 13) | TOP2[rmask & ~t3],
        (2 << 26) | (p2 << 13) | TOP1[rmask & ~p2],
        (1 << 26) | (ge2 << 13) | TOP3[rmask & ~ge2],
    ]
    return np.select(conds, vals, default=TOP5[rmask])


def strength(cards, draws=True):
    """Float strength metric: category + kicker fraction + draw bonus."""
    sc = evaluate(cards)
    cat = sc >> 26
    v = cat + (sc & SUBMASK) / float(1 << 26)
    if draws:
        S = cards & 3
        maxsuit = np.max(np.stack([(S == s).sum(1) for s in range(4)], 1), 1)
        rmask = np.bitwise_or.reduce(np.left_shift(1, cards >> 2).astype(np.int64), axis=1)
        bonus = 0.9 * (maxsuit == 4) + 0.35 * DRAW[rmask]
        v = v + np.where(cat < 4, bonus, 0.0)
    return v


# keep option i discards card i
KEEPS = ((1, 2), (0, 2), (0, 1))


def keep_values(h3, flop):
    """h3 (N,3), flop (N,3) -> (N,3) heuristic value of keeping each pair."""
    return np.stack([strength(np.concatenate([h3[:, kp], flop], 1)) for kp in KEEPS], 1)


def heuristic_keep(h3, flop):
    """Kept 2 cards (N,2) under the flop heuristic."""
    idx = np.argmax(keep_values(h3, flop), 1)
    kp = np.array(KEEPS)[idx]  # (N,2)
    return np.take_along_axis(h3, kp, 1), idx


def sample_cards(deck, n_rows, m):
    """n_rows samples of m distinct cards from deck (1-D array)."""
    r = RNG.random((n_rows, len(deck)))
    idx = np.argpartition(r, m, axis=1)[:, :m] if m < len(deck) else np.argsort(r, 1)
    return deck[idx]


